// Measured results, generated by `python eval/publish_results.py` from the eval
// harness and the C++ benchmark. Pages read numbers from here — never type them in.
import summary from "@/eval/results/summary.json";
import mem0Summary from "@/eval/results/mem0_comparison/summary.json";

export interface HnswResult {
    impl?: string; n: number; dim: number; data: string; M: number; efConstruction: number; efSearch: number;
    simd?: string; recall_at_10: number; search_avg_ms: number; search_p50_ms?: number; search_p99_ms?: number;
    build_seconds: number; ingest_us_per_vector?: number;
}

export interface RetrievalMetrics {
    "hit@1": number; "hit@3": number; stale_top: number; false_abstain_rate: number; abstain_accuracy: number;
    recall_ms_p50?: number; recall_ms_p95?: number; store_ms_p50?: number; store_stage_ms_mean?: Record<string, number>;
}

export interface ExampleRun {
    stores: { content: string; importance: number; schemas: string[]; promoted: boolean; slots: string[] }[];
    query: string;
    recall: {
        status: string; latency_ms: number; threshold: number;
        memories: { content: string; relevance: number; explain: Record<string, number> }[];
    };
}

export interface EvalRun {
    split: string; embedder: string; engine?: string; ranker_model?: string;
    facts?: { precision: number; recall: number; f1: number };
    schemas?: { accuracy: number };
    importance?: { auc: number; accuracy: number };
    retrieval?: RetrievalMetrics;
    legacy?: { gauntlet_passed: number; gauntlet_total: number; retention_hits: number; retention_total: number };
    example?: ExampleRun;
}

export interface SystemScores {
    [category: string]: { [metric: string]: number };
}

export interface LongMemEvalRun {
    file?: string; deep_recall?: boolean; stored_in_earlier_run?: boolean;
    questions: number; turns: number; embedder: string; engine: string; answer_check?: string;
    systems: Record<string, SystemScores>;
    abstention: { unanswerable_declined: number; answerable_wrongly_declined: number; n_unanswerable: number;
                  n_answerable: number; auc_top_relevance: number; auc_answer_margin: number | null };
}

export interface LoCoMoRun {
    file?: string; split: string; conversations: number; turns: number; questions: number; embedder: string; engine: string;
    systems: Record<string, SystemScores>;
    abstention: { adversarial_declined: number; answerable_wrongly_declined: number; n_adversarial: number; n_answerable: number };
}

export interface Summary {
    generated_at: string; git_commit: string;
    machine: { system: string; machine: string; cpu?: string; python?: string };
    eval: Record<string, EvalRun>;
    hnsw: HnswResult[];
    hnsw_reference: HnswResult[];
    longmemeval?: LongMemEvalRun[];
    locomo?: LoCoMoRun[];
}

export const results = summary as unknown as Summary;
export const hnsw: HnswResult[] = results.hnsw || [];
export const hnswReference: HnswResult[] = results.hnsw_reference || [];
/** The embedding model the shipped fits belong to (config.yaml models.embedding); older runs stay in eval/results. */
export const CURRENT_EMBEDDER = "st:BAAI/bge-small-en-v1.5";
const current = (e: string) => e === CURRENT_EMBEDDER || e === "hash";

/** Our own splits (dev, test) with the current embedder, plus the hash stand-in used in CI. */
export const evalRuns: EvalRun[] = Object.values(results.eval || {})
    .filter(r => ["dev", "test"].includes(r.split) && current(r.embedder));
const lmeRuns: LongMemEvalRun[] = results.longmemeval || [];
/** LongMemEval as shipped (default recall), and with deep recall on every question. */
export const longMemEval: LongMemEvalRun | undefined =
    lmeRuns.find(r => r.file === "longmemeval_s_bge-small-en-v1.5") ?? lmeRuns[lmeRuns.length - 1];
export const longMemEvalDeep: LongMemEvalRun | undefined = lmeRuns.find(r => r.file === "longmemeval_s_bge-small-en-v1.5_deep");
/** With recall.keep_results_on_decline (off by default): a decline still returns its results, marked low-confidence. */
export const longMemEvalKeep: LongMemEvalRun | undefined = lmeRuns.find(r => r.file === "longmemeval_s_bge-small-en-v1.5_keep-on-decline");
export const longMemEvalKeepDeep: LongMemEvalRun | undefined = lmeRuns.find(r => r.file === "longmemeval_s_bge-small-en-v1.5_keep-on-decline_deep");
export const locomoRuns: LoCoMoRun[] = (results.locomo || []).filter(r => r.embedder === CURRENT_EMBEDDER);

/* Head-to-head with Mem0 (eval/mem0_comparison, summarize.py). */
export interface Mem0Comparison {
    date: string; protocol: string; openai_spend_total_usd: number; notes: string[];
    scope: { dataset: string; conversations: string[]; messages: number; questions: number; answerable: number; adversarial: number;
             per_category: Record<string, number> };
    setup: { mem0: string; recallix: string; answer_and_judge: string };
    accuracy: Record<"recallix" | "mem0", { accuracy_overall: number; accuracy_answerable: number; adversarial_declined: number;
                                            by_category: Record<string, number> }>;
    significance: Record<"all" | "answerable", { only_recallix_right: number; only_mem0_right: number; p: number }>;
    store: Record<"recallix" | "mem0", { llm_calls: number; usd: number; ms_p50: number; ms_p95: number }>;
    recall_ms: Record<"recallix" | "mem0", { p50: number; p95: number }>;
}
export const mem0Comparison = mem0Summary as unknown as Mem0Comparison;

/** Median write-time ratio, rounded to one significant figure ("about 200×"). */
export const writeSpeedup = (c: Mem0Comparison) => {
    const r = c.store.mem0.ms_p50 / c.store.recallix.ms_p50;
    const mag = Math.pow(10, Math.floor(Math.log10(r)));
    return Math.round(r / mag) * mag;
};

/** Mem0's measured storage cost per message, extrapolated to a million messages, rounded to $100. */
export const perMillion = (c: Mem0Comparison) => Math.round((c.store.mem0.usd / c.scope.messages) * 1e6 / 100) * 100;

/** The headline run: held-out test split with the real (non-hash) embedder. */
export const headline: EvalRun | undefined = evalRuns.find(r => r.split === "test" && r.embedder !== "hash");

/** Largest benchmark on clustered data (closest to real embeddings). */
export const largestClustered: HnswResult | undefined = [...hnsw].filter(r => r.data === "clustered").sort((a, b) => b.n - a.n)[0];

export const pct = (x: number | undefined, digits = 0) =>
    x === undefined || x === null || Number.isNaN(x) ? "—" : `${(x * 100).toFixed(digits)}%`;
export const ms = (x: number | undefined, digits = 2) =>
    x === undefined || x === null ? "—" : `${x.toFixed(digits)} ms`;

/** Relative improvement of a over b, e.g. 0.18 for +18%. */
export const lift = (a?: number, b?: number) => (a === undefined || b === undefined || !b ? undefined : a / b - 1);

/** "+12%" / "−6%": a signed percentage that never reads "+-6%". */
export const signedPct = (x: number) => `${x >= 0 ? "+" : "−"}${Math.abs(Math.round(x * 100))}%`;

/**
 * The independent benchmark to headline: LongMemEval (fresh, held out) when published,
 * otherwise LoCoMo's test split. Returns overall recall@10 for Recallix's ranking
 * (`ranked`), for what Recallix serves after the answer check (`served`), and for
 * the baselines, plus abstention rates. Both Recallix numbers are shown on the site.
 */
export function headlineBenchmark() {
    if (longMemEval) {
        const s = longMemEval.systems;
        return {
            name: "LongMemEval", questions: longMemEval.questions,
            ranked: s.recallix_ranked?.overall?.["recall@10"], served: s.recallix?.overall?.["recall@10"],
            dense: s.dense?.overall?.["recall@10"], bm25: s.bm25?.overall?.["recall@10"],
            declined: longMemEval.abstention.unanswerable_declined, wronglyDeclined: longMemEval.abstention.answerable_wrongly_declined,
            nUnanswerable: longMemEval.abstention.n_unanswerable,
        };
    }
    const t = locomoRuns.find(r => r.split === "test");
    if (!t) return undefined;
    return {
        name: "LoCoMo (test split)", questions: t.questions,
        ranked: t.systems.recallix_ranked?.overall?.["recall@10"], served: t.systems.recallix?.overall?.["recall@10"],
        dense: t.systems.dense?.overall?.["recall@10"], bm25: t.systems.bm25?.overall?.["recall@10"],
        declined: t.abstention.adversarial_declined, wronglyDeclined: t.abstention.answerable_wrongly_declined,
        nUnanswerable: t.abstention.n_adversarial,
    };
}
